/*
 * USBSID-Player: a cycle exact C64 SID player for USBSID-Pico, for command
 * line playback and for embedding on RP2350 (Pico2).
 *
 * boot_image.h
 * Generated. Do not edit: run temp/tools/gen_boot_image.cpp instead.
 *
 * The state a C64 is in once the KERNAL has booted to the BASIC prompt,
 * as the difference from a machine that has just powered on.
 *
 * Reaching this state by running the KERNAL costs 2 240 002 cycles, which
 * on the device is 1.7 seconds of silence before every tune. The answer is
 * the same every time, because it depends only on the ROMs, so it is worked
 * out once here and written back instead.
 *
 * Only the difference is stored: the power on pattern is sixty four bytes
 * of $00 then sixty four of $ff repeated, so any byte of it follows from
 * its address and only the ones that do not match need keeping.
 *
 * This file is part of USBSID-Pico (https://github.com/LouDnl/USBSID-Player)
 * File author: LouD
 *
 * Copyright (c) 2026 LouD
 *
 * This program is free software: you can redistribute it and/or modify
 * it under the terms of the GNU General Public License as published by
 * the Free Software Foundation, version 2.
 *
 * This program is distributed in the hope that it will be useful, but
 * WITHOUT ANY WARRANTY; without even the implied warranty of
 * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the GNU
 * General Public License for more details.
 *
 * You should have received a copy of the GNU General Public License
 * along with this program. If not, see <http://www.gnu.org/licenses/>.
 *
 */

